DROP TABLE IF EXISTS `outcomes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `outcomes` (
  `outcome_id` bigint NOT NULL AUTO_INCREMENT,
  `intake_id` bigint NOT NULL,
  `outcome_date` datetime NOT NULL,
  `outcome_group` varchar(100) NOT NULL,
  `euthanasia_reason` varchar(255) DEFAULT NULL,
  `days_in_shelter` int DEFAULT NULL,
  PRIMARY KEY (`outcome_id`),
  UNIQUE KEY `intake_id` (`intake_id`),
  KEY `idx_outcome_group_date` (`outcome_group`,`outcome_date`),
  CONSTRAINT `outcomes_ibfk_1` FOREIGN KEY (`intake_id`) REFERENCES `intakes` (`intake_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `outcomes_chk_1` CHECK (((`days_in_shelter` is null) or (`days_in_shelter` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=32768 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
