CREATE TABLE `prescriptions` (
  `prescription_id` bigint NOT NULL AUTO_INCREMENT,
  `record_id` bigint NOT NULL,
  `medication_id` int NOT NULL,
  `quantity` int NOT NULL,
  `dosage` varchar(120) DEFAULT NULL,
